import {C,rect,text,line,arrow,swap} from './svg.js';import {layout} from './layout.js';
function joint(tx,bx,y,r,height,damage,id){let out=`<path data-joint="${id}" d="M${tx-r*.8} ${y}Q${tx-r*1.15} ${y+height*.35} ${bx-r*.85} ${y+height}H${bx+r*.85}Q${tx+r*1.15} ${y+height*.35} ${tx+r*.8} ${y}Z" fill="${C.tin}" stroke="${C.line}" stroke-width="1.2"/>`;out+=rect(tx-r*.9,y-5,r*1.8,5,C.copper)+rect(bx-r*.9,y+height,r*1.8,5,C.copper);if(damage>0){const end=tx+r*.8-damage*r*1.28;out+=`<path data-crack="${id}" d="M${tx+r*.82} ${y+7}L${tx+r*.8-damage*r*.4} ${y+9}L${tx+r*.8-damage*r*.85} ${y+7}L${end} ${y+10}" stroke="${C.paper}" stroke-width="3.5" fill="none"/>`;out+=line(tx+r*.8,y+7,end,y+9,'#985E48',1.2);}return out;}
export function draw(s,size){const{w,h,mobile,f,cx,cy,bw,k,zx,zy,zw,zh}=layout(size),sw=swap(s.t,29,34,w),temp=sw.fresh?0:s.temp,d=sw.fresh?0:s.damage,topw=bw*(1+.025*temp),bottomw=bw*(1+.075*temp),jy=cy+18*k,jh=37*k;let out=text(w/2,25,s.caption,f,C.muted);out+=`<g transform="translate(${sw.x} 0)">`;
out+=rect(cx-topw/2,cy-15*k,topw,33*k,C.silicon)+text(cx,cy+7*k,'上方封裝',f)+rect(cx-bottomw/2,jy+jh+5,bottomw,27*k,C.green)+text(cx,jy+jh+23*k,'電路板',f);
out+=line(cx,cy-(mobile?28:42),cx,cy-17*k,C.muted,1,'stroke-dasharray="4 4"')+text(cx,cy-(mobile?33:48),'共同中心',13,C.muted);
for(let i=-3;i<=3;i++){const pos=i*bw/8,tx=cx+pos*(1+.025*temp),bx=cx+pos*(1+.075*temp);out+=joint(tx,bx,jy,Math.min(18,bw/19),jh,i===3?d:0,'main-'+i);if(i===3){out+=`<rect x="${Math.min(tx,bx)-23}" y="${jy-8}" width="${46+Math.abs(tx-bx)}" height="${jh+21}" rx="4" fill="none" stroke="#B47D59" stroke-width="1.5"/>`;}}
if(Math.abs(temp)>.1){out+=arrow(temp>0?cx+15:cx+topw/2-5,cy-26,temp>0?cx+topw/2-5:cx+15,cy-26,'#A77759',1.4)+arrow(temp>0?cx+15:cx+bottomw/2-5,jy+jh+43,temp>0?cx+bottomw/2-5:cx+15,jy+jh+43,'#A77759',1.4);}
const rr=zw*.37,tx=zx-12*temp,bx=zx+12*temp,ty=zy-zh/2;out+=text(zx,ty-24,'右外側焊點 · 同步放大',f)+rect(zx-zw/2-12,ty-12,zw+24,zh+37,'none','stroke-dasharray="3 4"');out+=rect(zx-zw/2,ty-9,zw,9,C.silicon)+rect(zx-zw/2,ty+zh+5,zw,9,C.green)+joint(tx,bx,ty,rr,zh,d,'zoom');out+=text(zx,ty+zh+39,d>0?'封裝側裂紋 · 仍有金屬通路':'固態接點 · 尚無可見裂紋',mobile?13:14,C.muted);
out+='</g>';out+=text(mobile?w/2:cx,Math.min(h-12,mobile?jy+jh+64:jy+jh+76),(sw.fresh?'室溫附近':s.thermal)+' · 形變放大示意',mobile?13:15,temp>.12?C.heat:temp<-.12?'#537E98':C.muted);return out;}
